/bin/bash -lc "python3 -B <<'PY'
import importlib.util,random,copy,json
p='leetcode/871/solution.py'
spec=importlib.util.spec_from_file_location('actual',p);m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
def oracle(t,s,a):
 best=len(a)+1
 for mask in range(1<<len(a)):
  fuel=s;pos=0;count=0
  for i,(x,v) in enumerate(a):
   if mask&(1<<i):
    fuel-=x-pos;pos=x
    if fuel<0:break
    fuel+=v;count+=1
  else:
   if fuel>=t-pos:best=min(best,count)
 return best if best<=len(a) else -1
cases=[(31,10,[[5,6],[10,12],[22,9]],2),(20,3,[[4,100],[5,1]],-1),(20,10,[], -1),(10,10,[],0),(21,5,[[5,8],[10,8]],2),(10**9,1,[[1,999999999]],1),(501,1,[[i,1] for i in range(1,501)],500)]
for t,s,a,e in cases:
 old=copy.deepcopy(a);got=m.Solution().minRefuelStops(t,s,a);assert got==e and old==a;print(t,s,'n='+str(len(a)),got)
r=random.Random(47913)
for _ in range(600):
 t=r.randrange(2,60);a=[[p,r.randrange(1,30)] for p in sorted(r.sample(range(1,t),r.randrange(min(8,t-1)+1)))];s=r.randrange(1,40);old=copy.deepcopy(a);assert m.Solution().minRefuelStops(t,s,a)==oracle(t,s,a) and a==old
print('Independent physical subset oracle: 600 cases passed, no input mutation')
PY"
